import sys
from math import isqrt

data = sys.stdin.buffer.read().split()
n = int(data[0])
word = data[1]
letters = [c - 97 for c in word]

divisors = set()
for d in range(1, isqrt(n) + 1):
    if n % d == 0:
        divisors.add(d)
        divisors.add(n // d)

for k in sorted(d for d in divisors if d <= n // 2):
    base = [0] * 26
    for i in range(k):
        base[letters[i]] += 1

    valid = True
    for start in range(k, n, k):
        counts = [0] * 26
        for i in range(start, start + k):
            counts[letters[i]] += 1
        if counts != base:
            valid = False
            break

    if valid:
        sys.stdout.write(word[:k].decode())
        break
else:
    sys.stdout.write("*")
